using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace FoolLauncher {
 public sealed class ModManagerPage {
  readonly Window Window;readonly PackService Service;readonly ModManager Manager;readonly Func<Instance> Selected;readonly Func<bool> Busy,Running;readonly Func<Func<IProgress<Update>,CancellationToken,Task>,Task> Runner;readonly Action<string> Navigate;readonly Border Page;readonly StackPanel Rows=new StackPanel();readonly TextBox Search=new TextBox();readonly TextBlock Title=new TextBlock(),Status=new TextBlock();readonly Button All=new Button(),Updates=new Button();LocalMod[] Items=new LocalMod[0];Instance Instance;bool OnlyUpdates;CancellationTokenSource Cancel;
  public ModManagerPage(Window window,PackService service,Func<Instance> selected,Func<bool> busy,Func<bool> running,Func<Func<IProgress<Update>,CancellationToken,Task>,Task> runner,Action<string> navigate){Window=window;Service=service;Manager=new ModManager(service);Selected=selected;Busy=busy;Running=running;Runner=runner;Navigate=navigate;Page=(Border)Window.FindName("ModManagerPage");var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var top=new StackPanel();Title.FontSize=24;Title.FontWeight=FontWeights.SemiBold;top.Children.Add(Title);Search.Margin=new Thickness(0,14,0,12);Search.Padding=new Thickness(12,10,12,10);Search.ToolTip="搜索模组名称、描述或文件名";Search.SetResourceReference(Control.BackgroundProperty,"Brush.Log");Search.SetResourceReference(Control.ForegroundProperty,"Brush.Text");Search.TextChanged+=(s,e)=>Render();top.Children.Add(Search);var buttons=new WrapPanel();buttons.Children.Add(Button("返回整合包库",()=>Navigate("library")));buttons.Children.Add(Button("打开文件夹",()=>OpenFolder()));buttons.Children.Add(Button("下载新 Mod",()=>Navigate("mods")));buttons.Children.Add(Button("刷新 / 检查更新",async()=>await Load(true)));buttons.Children.Add(Button("停止任务",()=>{if(Cancel!=null)Cancel.Cancel();}));top.Children.Add(buttons);var tabs=new WrapPanel{Margin=new Thickness(0,14,0,10)};All.Click+=(s,e)=>{OnlyUpdates=false;Render();};Updates.Click+=(s,e)=>{OnlyUpdates=true;Render();};tabs.Children.Add(All);tabs.Children.Add(Updates);top.Children.Add(tabs);grid.Children.Add(top);var scroll=new ScrollViewer{Content=Rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);grid.Children.Add(scroll);Status.TextWrapping=TextWrapping.Wrap;Status.FontSize=12;Status.Margin=new Thickness(0,12,0,0);Status.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");Grid.SetRow(Status,2);grid.Children.Add(Status);Page.Child=grid;}
  Button Button(string text,Action action){var b=new Button{Content=text,Padding=new Thickness(12,8,12,8),Margin=new Thickness(0,0,8,4)};b.Click+=(s,e)=>{try{action();}catch(Exception ex){Status.Text=ex.Message;}};return b;}
  public void Show(bool visible){Page.Visibility=visible?Visibility.Visible:Visibility.Collapsed;if(!visible){if(Cancel!=null)Cancel.Cancel();return;}var selected=Selected();if(selected==null)return;if(Instance==null||Instance.Id!=selected.Id){Instance=selected;Items=new LocalMod[0];Search.Clear();OnlyUpdates=false;}Title.Text=Instance.Name+" · Mod 管理";var ignored=Load(false);}
  async Task Job(Func<IProgress<Update>,CancellationToken,Task> work){if(Busy())return;await Runner(async(p,ct)=>{Cancel=CancellationTokenSource.CreateLinkedTokenSource(ct);var progress=new Progress<Update>(u=>{Status.Text=u.Message;p.Report(u);});try{await work(progress,Cancel.Token);}catch(OperationCanceledException){Status.Text="任务已停止，已安装模组保持原样。";}finally{Cancel.Dispose();Cancel=null;Render();}});}
  async Task Load(bool force){if(Instance==null||Busy())return;var instance=Instance;if(Running()){Items=await Task.Run(()=>Manager.List(instance,CancellationToken.None));Render();Status.Text="游戏运行中，可以查看模组；请退出 Prism 和游戏后修改或检查更新。";return;}await Job(async(p,ct)=>{Items=await Task.Run(()=>Manager.List(instance,ct),ct);Render();Status.Text="正在检查兼容的新版本（只检查，不自动安装）…";await Manager.Check(instance,Items,p,ct,force);Render();int failed=Items.Count(m=>(m.CheckNote??"").StartsWith("未识别"));Status.Text="共 "+Items.Length+" 个模组，可更新 "+Items.Count(m=>m.Update!=null)+" 个；未识别或检查失败 "+failed+" 个。仅列出兼容的新正式版，更新需手动选择。";});}
  void OpenFolder(){if(Instance==null)return;string path=Path.Combine(Service.Game(Instance),"mods");Directory.CreateDirectory(path);Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
  void Render(){Rows.Children.Clear();All.Content="全部 ("+Items.Length+")";Updates.Content="可更新 ("+Items.Count(m=>m.Update!=null)+")";foreach(var mod in Items.Where(m=>(!OnlyUpdates||m.Update!=null)&&(String.IsNullOrWhiteSpace(Search.Text)||(m.Title+" "+m.Detail).IndexOf(Search.Text,StringComparison.OrdinalIgnoreCase)>=0))){var row=mod;var card=new Border{CornerRadius=new CornerRadius(7),Padding=new Thickness(10),Margin=new Thickness(0,0,0,5)};card.SetResourceReference(Border.BackgroundProperty,"Brush.Log");var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var image=new Image{Source=mod.Icon,Width=34,Height=34,Margin=new Thickness(0,0,12,0)};grid.Children.Add(image);var text=new StackPanel();var title=new TextBlock{Text=mod.Title,FontWeight=FontWeights.SemiBold,TextTrimming=TextTrimming.CharacterEllipsis,ToolTip=mod.Title};text.Children.Add(title);var detail=new TextBlock{Text=mod.Detail,FontSize=11,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,5,0,0),ToolTip=mod.Detail+"\n"+mod.CheckNote};detail.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");text.Children.Add(detail);Grid.SetColumn(text,1);grid.Children.Add(text);var actions=new StackPanel{Orientation=Orientation.Horizontal,Visibility=Visibility.Collapsed,VerticalAlignment=VerticalAlignment.Center};
   actions.Children.Add(Small("ⓘ","查看 MC 百科（未匹配时搜索名称）",()=>{int id=Manager.Names.Wiki(row.Source,row.Slug);string url=id>0?"https://www.mcmod.cn/class/"+id+".html":"https://search.mcmod.cn/s?key="+Uri.EscapeDataString(row.Name);Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}));actions.Children.Add(Small("▱","定位文件",()=>Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+PackService.SafePath(Path.Combine(Service.Game(Instance),"mods"),row.File)+"\""){UseShellExecute=true})));actions.Children.Add(Small(row.Disabled?"⊕":"⊖",row.Disabled?"启用":"禁用",async()=>{if(Busy()||Running())return;var instance=Instance;await Job(async(p,ct)=>{await Task.Run(()=>Manager.Change(instance,row,false,ct),ct);Items=await Task.Run(()=>Manager.List(instance,ct),ct);Status.Text=row.Disabled?"已启用模组。":"已禁用模组，校验不会重新下载它。";});}));actions.Children.Add(Small("♲","删除并备份",async()=>{if(Busy()||Running())return;if(!DeleteConfirmation.Show(Window,"删除模组",row.Name,"从当前整合包移除此模组，并同步更新文件清单。","原文件保留在该整合包的 mod-backups 中，可以恢复。","删除并备份"))return;var instance=Instance;await Job(async(p,ct)=>{await Task.Run(()=>Manager.Change(instance,row,true,ct),ct);Items=await Task.Run(()=>Manager.List(instance,ct),ct);Status.Text="模组已删除并备份；校验不会重新下载它。";});}));
   if(mod.Update!=null){var update=Small("↑","手动更新到 "+mod.Update.Number,async()=>{if(Busy()||Running())return;if(row.Disabled){Status.Text="请先启用此模组，再更新。";return;}if(!DeleteConfirmation.Show(Window,"更新模组",row.Name+" → "+row.Update.Number,"将安装此版本及其必需前置。整合包作者可能有版本搭配要求，请自行决定是否更新。","旧版文件会保存在 mod-backups；不会自动更新其他可更新项目。","更新此模组"))return;var instance=Instance;await Job(async(p,ct)=>{string file=PackService.SafePath(Path.Combine(Service.Game(instance),"mods"),row.File);if(ModManager.Read(file).Hash!=row.Hash)throw new IOException("模组文件已变化，请刷新。");await new CatalogInstaller(Service,new CatalogService(),CatalogNetwork.Download,Running).Install(ModTarget.Capture(Service,instance),row.Update,p,ct);Items=await Task.Run(()=>Manager.List(instance,ct),ct);Status.Text="更新完成。旧版已备份，必需前置已处理。";});});actions.Children.Add(update);}
   Grid.SetColumn(actions,2);grid.Children.Add(actions);card.MouseEnter+=(s,e)=>actions.Visibility=Visibility.Visible;card.MouseLeave+=(s,e)=>actions.Visibility=Visibility.Collapsed;card.Child=grid;Rows.Children.Add(card);}}
  Button Small(string glyph,string tip,Action action){var b=Button(glyph,action);b.ToolTip=tip;b.Padding=new Thickness(7,5,7,5);b.FontSize=17;if(glyph=="♲"){var icon=new System.Windows.Shapes.Path{Data=Geometry.Parse("M 1,4 L 17,4 M 6,4 L 6,1 L 12,1 L 12,4 M 3,4 L 4,20 L 14,20 L 15,4 M 7,8 L 7,16 M 11,8 L 11,16"),Width=16,Height=19,Stretch=Stretch.Uniform,StrokeThickness=1.6};icon.SetResourceReference(System.Windows.Shapes.Shape.StrokeProperty,"Brush.Danger");b.Content=icon;}b.Margin=new Thickness(3,0,0,0);return b;}
 }
}
